import java.util.*;
public class LeaseTest{
 public static void main(String[]args){InterestRegistry r=new InterestRegistry();String a=r.create(0),b=r.create(0);r.renew(a,Arrays.asList(1,2),1);r.renew(b,Arrays.asList(2,3),1);if(r.union().size()!=3)throw new AssertionError("Union not deduplicated");r.release(a);if(!r.union().equals(new HashSet<>(Arrays.asList(2,3))))throw new AssertionError("Viewer release removed shared subscription");r.expire(InterestRegistry.TTL+2);if(r.size()!=0||!r.union().isEmpty())throw new AssertionError("Lease leak");try{r.renew(b,Arrays.asList(1),InterestRegistry.TTL+3);throw new AssertionError("Expired lease resurrected");}catch(IllegalArgumentException expected){}for(int i=0;i<8;i++)r.create(0);try{r.create(0);throw new AssertionError("Viewer limit");}catch(IllegalStateException expected){}Object json=Json.object("{\"msg\":\"тест\\n🟢\",\"ids\":[1,2],\"ok\":true}");if(!Json.object(Json.write(json)).equals(json))throw new AssertionError("JSON roundtrip");System.out.println("PASS leases: shared-interest deduplication, partial release, expiry, bounded viewers, no resurrection, JSON roundtrip");}
}
